// Core strategy: Use indirection (stubs or jump tables)
// to decouple modules, avoiding full relink when offsets change.

// Module B: Actual function location
int TargetFunc(int arg) { return arg * arg; }

// GLUE CODE / STUB (Stable, known address)
// Only this pointer is updated during incremental linking.
void* Stub_TargetFunc = (void*)&TargetFunc;

// Module A: Caller uses the stable stub
typedef int (*FuncPtr)(int);

int Caller() {
    FuncPtr func = (FuncPtr)Stub_TargetFunc;
    return func(10);
}

// If TargetFunc moves, only Stub_TargetFunc needs updating.
// Module A remains untouched.
